import os
from google.cloud import translate_v2 as translate

def translate_dictionary_values(dictionary, target_language):
    client = translate.Client()
    translated_dict = {}
    for key, value in dictionary.items():
        translated_dict[key] = client.translate(value, target_language=target_language)['translatedText']
    return translated_dict

import os
from google.cloud import translate_v2 as translate

def get_translation_client():
    os.environ['GOOGLE_APPLICATION_CREDENTIALS'] = 'path/to/your/credentials.json'
    return translate.Client()

class TranslationRequest:
    def __init__(self, text, target_language):
        self.text = text
        self.target_language = target_language

class TranslationResponse:
    def __init__(self, translated_text):
        self.translated_text = translated_text

def normalize_translation_response(response):
    return TranslationResponse(response['translatedText'])

import os
from google.cloud import translate_v2 as translate

def summarize_quality_issues(translations):
    client = translate.Client()
    issues = []
    for translation in translations:
        result = client.translate(translation, target_language='en')
        if result['detectedSourceLanguage']!= 'en':
            issues.append(f'Potential mistranslation: {translation}')
    return issues
